import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`retirement-planner`,heroTitle:`Build your retirement plan in minutes`,heroSubtitle:`Perplexity Computer analyzes your portfolio, models your goals, and delivers a full retirement plan — automatically.`,heroCta:`Plan my retirement`,inputUrlPrefill:`Come up with a retirement plan for me and show me where I currently stand. Connect my investment and retirement accounts via Plaid (401k, IRA, brokerage, etc.). Then ask me about my target retirement age, desired annual retirement income, expected Social Security benefits, current contribution rates, risk tolerance, and any pensions or other retirement income sources. Build me a plan and show me if I’m on track.`,heroOverlaySteps:[`Connecting to your portfolio and gathering current holdings`,`Modeling projected growth, income needs, and withdrawal strategies`,`Identifying gaps between your current trajectory and retirement goals`,`Retirement roadmap, allocation recommendations, and milestone tracker — ready to review`],featureSectionTitle:`From portfolio to plan`,featureCardTitles:[`Connects to your finance stack`,`Outputs you can act on`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, QuickBooks, Airtable, Google Drive — Computer plugs into your tools so portfolio tracking, projections, and planning happen in one workflow.`,`Portfolio gap analysis. Retirement income projections. Asset allocation recommendations. Tax-efficient withdrawal strategies. A milestone-by-milestone roadmap to your target date.`],capabilitySectionTitle:`Your financial planner, on autopilot`,capabilitySectionSubtitle:`Share your goals, step away, come back to a complete retirement strategy.`,capabilityCards:[{title:`Portfolio Analysis`,description:`Computer can break down your current holdings — asset allocation, risk exposure, fee drag, diversification gaps — and deliver a prioritized improvement list.`},{title:`Retirement Projections`,description:`Computer can model multiple scenarios across different contribution rates, market conditions, and retirement ages to show where you stand today.`},{title:`Withdrawal Strategy`,description:`Computer can design tax-efficient drawdown plans — Roth conversions, Social Security timing, required minimum distributions — tailored to your accounts.`},{title:`Connect Your Tools`,description:`Computer can read from Google Sheets, QuickBooks, Google Drive, and more — build workflows across your entire financial stack.`},{title:`Remember & Learn`,description:`Computer can remember your risk tolerance, accounts, and goals across sessions — so every update builds on your existing plan.`},{title:`Monitor & Alert`,description:`Computer can watch your portfolio allocation and market shifts — set up a monitoring workflow that flags when rebalancing or plan adjustments are needed.`}]});export{t as default};
